    W=['','a','кот','Pandora','  ветер  ','moon-light','АБВ абв','a_b_c','0007','rain.rain']
    add('elevator_skip','Лифт без четвёртого','data — номер этажа 1..200. В доме пропущены все этажи, оканчивающиеся на 4: 4,14,24… Верни число реально существующих этажей от 1 до data включительно.','return data-(data+6)//10',[1,3,4,5,13,14,24,104,200],'math_ops')
    add('robot_turn','Робот на перекрёстке','data=[направление,повороты], направление 0..3 (север,восток,юг,запад), повороты — целое число четвертей оборота вправо; отрицательное означает влево. Верни новое направление.','return (data[0]+data[1])%4',[[0,0],[0,-1],[3,1],[2,9],[1,-10],[3,4],[0,100],[2,-3]],'math_ops')
    add('sleepy_clock','Сонные часы','data — целое число минут после полуночи, может быть отрицательным. Часы повторяют сутки. Верни строку HH:MM с ведущими нулями.','return f"{data//60%24:02d}:{data%60:02d}"',[-1,0,1,59,60,1439,1440,2881],'strings')
    add('chocolate_cuts','Шоколад без крошек','data=[строки,столбцы], оба положительные. Шоколад ломают по одному куску за раз по линиям клеток. Верни минимальное число разломов до отдельных клеток.','return data[0]*data[1]-1',[[1,1],[1,2],[2,2],[2,5],[7,3],[9,9],[1,100],[12,11]],'math_ops')
    add('silent_bell','Беззвучный будильник','data — номер минуты от 0. Будильник мигает на каждой третьей минуте, но молчит на каждой пятой. Верни bool: мигает ли он сейчас.','return data%3==0 and data%5!=0',N,'if_else')
    add('sand_hourglass','Два песочных таймера','data=[a,b], a≥0, b≥1 — секунды работы и длительность одного таймера. После окончания таймер переворачивают мгновенно. Верни секунды до следующего окончания; в момент окончания верни b.','return data[1]-data[0]%data[1]',P,'math_ops')
    add('odd_door','Дверь с двумя ключами','data=[a,b], целые числа. Дверь открывается, если ровно одно из них отрицательное. Верни bool.','return (data[0]<0)!=(data[1]<0)',[[-1,2],[2,-1],[-1,-2],[0,0],[0,-7],[9,0],[3,4],[-8,0]],'if_else')
    add('broken_key','Залипшая клавиша','data — строка. Клавиатура удваивает только первый символ, остальной текст не меняется. Верни полученную строку. Пустая остаётся пустой.','return data[:1]+data',W,'strings')
    add('nameplate','Табличка у зеркала','data — строка. Поменяй местами её первый и последний символы; при длине меньше 2 ничего не меняй.','return data[-1:]+data[1:-1]+data[:1] if len(data)>1 else data',W,'strings')
    add('missing_button','Кнопка посередине','data — строка. Удали один центральный символ при нечётной длине, два центральных при чётной. Верни остаток. Пустая строка остаётся пустой.','n=len(data)\nreturn data[:(n-1)//2]+data[n//2+1:] if n else ""',W,'strings')
    add('laser_point','Луч в квадрате','data=[x,y], целые координаты. Верни bool: находится ли точка на границе квадрата -5≤x,y≤5. Внешние точки не подходят.','x,y=data\nreturn max(abs(x),abs(y))==5',[[5,0],[0,5],[-5,-5],[4,4],[6,5],[0,0],[5,7],[2,-5]],'if_else')
    add('coin_flip','Монета с памятью','data=[старт,броски], старт равен 0 или 1, броски≥0. Каждый бросок меняет сторону. Верни конечную сторону.','return data[0]^(data[1]%2)',[[0,0],[1,0],[0,1],[1,1],[0,9],[1,10],[1,99],[0,200]],'math_ops')
    add('alarm_digits','Две лампы счётчика','data — целое 0..9999. Верни bool: совпадают ли последние две десятичные цифры, считая ведущие нули.','return data%10==data//10%10',[0,1,11,22,101,100,9999,1234],'if_else')
    add('rail_wheel','Колесо вагона','data=[метры,окружность], метры≥0, окружность≥1. Датчик срабатывает каждый раз после полного оборота и ещё один раз на старте. Верни число срабатываний.','return data[0]//data[1]+1',P,'math_ops')
    add('bit_lantern','Фонарь младшего бита','data — неотрицательное целое. Верни вес младшего установленного двоичного бита; для нуля верни 0.','return data & -data',N,'math_ops')
    add('binary_toggle','Секретный переключатель','data — неотрицательное целое. Инвертируй ровно третий двоичный бит справа (вес 4), остальные сохрани. Верни число.','return data ^ 4',N,'math_ops')
    add('last_digit_rotate','Цифра уходит вперёд','data — целое от 100 до 999. Перенеси последнюю цифру в начало трёхзначной записи и верни число; ведущий ноль исчезает.','return data%10*100+data//10',[100,101,120,123,405,678,990,999],'math_ops')
    add('digit_product','Три светящихся цифры','data — целое 0..999. Запиши его тремя цифрами с ведущими нулями и верни произведение этих цифр.','return data//100*(data//10%10)*(data%10)',[0,7,100,123,222,405,789,999],'math_ops')
    add('mirror_number','Зеркало четырёх цифр','data — целое 0..9999. Переверни четырёхзначную запись с ведущими нулями и верни целое число.','return int(f"{data:04d}"[::-1])',[0,1,10,120,1000,1234,9001,9999],'strings')
    add('battery_cells','Батарейки через одну','data — число батареек n≥0. Они пронумерованы 1..n; работают батарейки, чей номер не делится на 3. Верни число рабочих.','return data-data//3',N,'math_ops')
    add('ticket_fold','Складной билет','data — строка. Левая половина имеет длину len(data)//2. Верни bool: совпадает ли она с перевёрнутой правой половиной той же длины; центр игнорируй. Пустая подходит.','n=len(data)//2\nreturn data[:n]==data[len(data)-n:][::-1]',['','a','abba','abcba','abcd','aa','ab','xyzzyx'],'strings')
    add('password_frame','Рамка пароля','data — строка. Замени все символы, кроме первого и последнего, на *. Для длины 0..2 верни исходную строку.','return data[:1]+"*"*max(0,len(data)-2)+data[-1:] if len(data)>1 else data',W,'strings')
    add('echo_gap','Сигнал с паузой','data=[слово,n], слово — строка, n≥0. Верни n копий слова через ровно один пробел, без пробела по краям.','return " ".join([data[0]]*data[1])',[['x',0],['x',1],['эхо',3],['',2],['a b',2],['!',5],['ab',4],['0',7]],'strings')
    add('door_initials','Инициалы двух миров','data=[имя,фамилия], строки могут быть пустыми. Верни первые символы обеих строк в верхнем регистре, между ними точка, точка также в конце. Пустая часть даёт пустое место.','return data[0][:1].upper()+"."+data[1][:1].upper()+"."',[['иван','ли'],['',''],['Ada','Lovelace'],['a',''],['','Б'],[' ёж','кот'],['ю','я'],['1','2']],'strings')
    add('portal_extension','Расширение портала','data — имя файла. Верни часть после последней точки в нижнем регистре. Если точки нет или она последняя, верни пустую строку.','return data.rsplit(".",1)[1].lower() if "." in data else ""',['file.py','a.tar.GZ','README','.env','a.','','x.js','photo.JPEG'],'strings')
    add('one_prefix','Одна приставка','data — строка. Удали ровно один префикс anti-, если строка с него начинается; регистр важен.','return data[5:] if data.startswith("anti-") else data',['anti-virus','anti-anti-x','Anti-x','xanti-y','anti-','','ant','обычно'],'strings')
    add('tiny_url','Карманный адрес','data — строка. Удали префикс https:// или http://, затем один завершающий /. Остальное не меняй.','s=data[8:] if data.startswith("https://") else data[7:] if data.startswith("http://") else data\nreturn s[:-1] if s.endswith("/") else s',['https://a/','http://a/b/','a/','/','','https://','ftp://x/','https://x//'],'strings')
    add('blank_meter','Измеритель пустоты','data — строка. Верни число пробелов только в начале строки. Учитывается символ обычного пробела, не табуляция.','return len(data)-len(data.lstrip(" "))',['',' ','  a','a  ','   ','\ta',' \ta','    кот'],'strings')
    add('vowel_gate','Гласная на входе','data — строка. Верни bool: начинается ли она с латинской гласной a,e,i,o,u без учёта регистра. Пустая не подходит.','return bool(data) and data[0].lower() in "aeiou"',['','Apple','owl','Umbra','red',' apple','Ice','ёж'],'if_else')
    add('exactly_question','Вопрос без крика','data — строка. Верни bool: оканчивается ли она на ? и не содержит ли !. Пробелы по краям игнорировать нельзя.','return data.endswith("?") and "!" not in data',['?','почему?','что!?','','да','? ','!нет?','a?b?'],'strings')
    add('signed_label','Табличка температуры','data — целое число. Верни строку с обязательным знаком + для неотрицательного числа и обычным - для отрицательного.','return f"{data:+d}"',[-100,-1,0,1,7,12,99,1000],'strings')
    add('weekday_weekend','Сосед выходного','data — номер дня 1..7, понедельник=1. Верни число дней до ближайшей будущей субботы, включая сегодняшнюю (в субботу 0).','return (6-data)%7',[1,2,3,4,5,6,7,1],'math_ops')
    add('leap_spring','Лишний день весны','data — год 1..9999 по григорианскому календарю. Верни bool: високосный ли он.','return data%400==0 or data%4==0 and data%100!=0',[1,4,100,400,1900,2000,2024,2100],'if_else')
    add('century_label','Век архивариуса','data — положительный год. Верни номер века; годы 1..100 относятся к первому веку.','return (data-1)//100+1',[1,99,100,101,1900,1901,2000,2026],'math_ops')
    add('night_tariff','Ночной тариф дрона','data=[час,минуты], час 0..23, минуты≥0. Полёт стоит 2 монеты за минуту, но при старте с 22 до 5 включительно ставка 3. Верни стоимость.','h,m=data\nreturn m*(3 if h>=22 or h<6 else 2)',[[0,1],[6,10],[21,5],[22,5],[5,7],[12,0],[23,60],[7,11]],'if_else')
    add('boiling_altitude','Чай на воздушном острове','data — высота в метрах, целое ≥0. Температура кипения равна 100 минус один градус за каждые полные 300 метров, но не меньше 60. Верни целую температуру.','return max(60,100-data//300)',[0,299,300,600,5000,12000,13000,20000],'math_ops')
    add('snail_day','Улитка до первого отдыха','data=[высота,подъём,спуск], высота≥1, подъём>спуск≥0. Улитка поднимается днём и сползает ночью; на вершине не сползает. Верни день достижения вершины, начиная с 1.','h,u,d=data\nreturn 1 if h<=u else 1+(h-u+u-d-1)//(u-d)',[[1,3,1],[6,3,1],[10,3,2],[8,4,0],[100,9,3],[9,9,8],[20,8,2],[30,7,6]],'math_ops')
    add('pollen_tiles','Пыльца на шахматном полу','data=[строка,столбец], положительные целые. Клетка (1,1) белая. Верни строку white или black для цвета клетки.','return "white" if (data[0]+data[1])%2==0 else "black"',[[1,1],[1,2],[2,1],[2,2],[7,8],[8,8],[3,9],[10,3]],'if_else')
    add('rook_look','Взгляд ладьи','data=[x1,y1,x2,y2], координаты 1..8. Верни bool: может ли ладья перейти из первой клетки во вторую за один ход; совпавшие клетки не считаются ходом.','a,b,c,d=data\nreturn (a==c or b==d) and (a,b)!=(c,d)',[[1,1,1,8],[1,1,8,1],[1,1,1,1],[2,3,4,5],[8,8,8,7],[2,2,3,2],[1,8,8,1],[4,5,4,1]],'if_else')
    add('bishop_look','Диагональ призрака','data=[x1,y1,x2,y2], координаты 1..8. Верни bool: может ли слон перейти между разными клетками за один ход.','a,b,c,d=data\nreturn abs(a-c)==abs(b-d) and a!=c',[[1,1,8,8],[2,3,3,4],[1,1,1,1],[1,1,1,8],[8,1,1,8],[3,2,4,4],[5,5,2,2],[7,2,6,3]],'if_else')
    add('knight_stamp','Штамп коня','data=[dx,dy], целые смещения. Верни bool: является ли смещение ходом шахматного коня.','return sorted(map(abs,data))==[1,2]',[[1,2],[-2,1],[0,0],[2,2],[1,-2],[3,1],[-1,-2],[0,2]],'if_else')
    add('king_distance','Путь короля','data=[x1,y1,x2,y2], целые координаты на бесконечной доске. Верни минимальное число ходов короля (на соседнюю клетку по стороне или диагонали).','return max(abs(data[0]-data[2]),abs(data[1]-data[3]))',[[0,0,0,0],[0,0,1,1],[1,2,8,5],[-3,4,2,-1],[9,9,0,0],[1,1,1,5],[2,7,3,1],[10,-10,-5,4]],'math_ops')
    add('segment_touch','Два отрезка света','data=[a,b,c,d], a≤b и c≤d — замкнутые интервалы на прямой. Верни bool: есть ли общая точка.','a,b,c,d=data\nreturn max(a,c)<=min(b,d)',[[0,2,2,4],[0,1,2,3],[1,1,1,1],[-4,-2,-3,0],[3,7,1,2],[0,10,2,3],[5,5,6,6],[0,0,-1,1]],'if_else')
    add('fold_distance','Сложенная линейка','data=[длина,отметка], длина≥0, 0≤отметка≤длина. Линейку сгибают пополам. Верни расстояние отметки до ближайшего исходного конца.','return min(data[1],data[0]-data[1])',[[0,0],[10,0],[10,5],[10,9],[7,3],[8,8],[100,27],[1,1]],'math_ops')
    add('clock_angle','Минутная стрелка','data=[часы,минуты], часы 0..23, минуты 0..59. Верни меньший угол между стрелками в половинах градуса (целое число, вдвое больше градусов).','h,m=data\na=abs((h%12)*60+m-12*m)%720\nreturn min(a,720-a)',[[0,0],[3,0],[6,0],[12,30],[23,59],[1,5],[9,15],[4,40]],'math_ops')
    add('trailing_digit','Правый ненулевой знак','data — положительное целое. Верни последнюю ненулевую цифру десятичной записи.','return int(str(data).rstrip("0")[-1])',[1,10,1200,700,12345,90001,100000,909090],'strings')
    add('one_cross','Крест из спичек','data=[горизонталь,вертикаль], положительные целые длины двух полос шириной 1. Полосы пересекаются ровно одной клеткой. Верни число клеток объединения.','return sum(data)-1',[[1,1],[1,4],[2,2],[7,3],[8,9],[20,1],[5,12],[99,10]],'math_ops')
    add('pixel_border','Рамка пиксельного окна','data=[высота,ширина], положительные целые. Верни число клеток на внешней рамке прямоугольника толщиной одну клетку; углы считай один раз.','h,w=data\nreturn h*w-max(0,h-2)*max(0,w-2)',[[1,1],[1,5],[2,7],[3,3],[4,6],[10,10],[3,8],[9,2]],'math_ops')
    add('row_ticket','Ряд в кинотеатре','data=[место,ширина], место≥1, ширина≥1. Места нумеруются подряд с 1. Верни [номер ряда с 1, номер места в ряду с 1].','n,w=data\nreturn [(n-1)//w+1,(n-1)%w+1]',[[1,1],[1,5],[5,5],[6,5],[31,8],[99,10],[120,17],[365,24]],'math_ops')
    add('snake_seat','Место в змейке','data=[ряд,ширина,позиция], ряд≥1, ширина≥1, 1≤позиция≤ширина. Первый ряд нумеруется слева направо, второй справа налево и так далее. Верни глобальный номер клетки в данной позиции слева.','r,w,p=data\nreturn (r-1)*w+(p if r%2 else w-p+1)',[[1,4,1],[1,4,4],[2,4,1],[2,4,4],[3,3,2],[4,7,3],[5,1,1],[6,8,6]],'math_ops')
    add('cone_signal','Конус света','data=[x,y]. Верни bool: точка находится в закрытом конусе y≥|x| и ниже или на высоте 10.','x,y=data\nreturn abs(x)<=y<=10',[[0,0],[5,5],[-5,5],[6,5],[0,11],[0,-1],[10,10],[9,10]],'if_else')
    add('round_tens','Округление без банкира','data — неотрицательное целое. Округли до ближайшего десятка, при равенстве выбери больший.','return (data+5)//10*10',N,'math_ops')
    add('third_stamp','Третий символ печати','data — строка. Верни третий символ с конца, а если символов меньше трёх — строку ?.','return data[-3] if len(data)>=3 else "?"',W,'strings')
    add('inside_quotes','Свиток в кавычках','data — строка. Сними ровно одну пару одинаковых внешних кавычек: одинарных или двойных. Иначе верни исходную строку.','return data[1:-1] if len(data)>=2 and data[0]==data[-1] and data[0] in "\\\"\u0027" else data',['"hi"',"'hi'",'hi','"',"''",'"a\u0027','""',' "x" '],'strings')
    add('star_gap','Пробелы становятся звёздами','data — строка. Замени каждую пару обычных пробелов на одну *. Непарный пробел сохрани; замены не повторяются.','return data.replace("  ","*")',['',' ','  ','   ','a  b','a    b',' a ','\t  x'],'strings')
    add('decimal_tail','Дробная табличка','data — строка, содержащая не больше одной точки. Верни часть справа от точки; если точки нет, верни пустую строку. Знаки и нули сохраняй.','return data.partition(".")[2]',['1.25','-0.007','42','.5','5.','','0.0','-3.1400'],'strings')
    add('sandwich_middle','Начинка бутерброда','data — строка. Верни bool: длина не меньше 3, а первый и последний символы равны и центральная часть не содержит этот символ.','return len(data)>=3 and data[0]==data[-1] and data[0] not in data[1:-1]',['aba','aaa','abca','aa','x','xyyx','ab','0abc0'],'if_else')
    add('case_switch','Переключатель регистра','data — строка. Поменяй регистр всех букв: строчные на прописные, прописные на строчные. Цифры и знаки сохрани.','return data.swapcase()',W,'strings')
    add('codepoint_step','Сосед Unicode','data — непустая строка из одного символа с кодом меньше 1114111. Верни следующий по коду Unicode символ.','return chr(ord(data)+1)',['a','z','0','9','А','я','!',' '],'strings')
    add('ascii_box','Коробка для букв','data — один символ. Верни bool: это ровно латинская буква A..Z или a..z.','return "a"<=data<="z" or "A"<=data<="Z"',['a','Z','я','1','!','m','É','_'],'if_else')
    add('digit_lock','Цифровой замок','data — строка. Верни bool: она состоит ровно из четырёх ASCII-цифр 0..9; любые другие символы запрещены.','return len(data)==4 and all("0"<=c<="9" for c in data)',['0000','1234','123','12345','１２３４','12a4','','-123'],'strings')
    add('balanced_scale','Весы двух чаш','data=[a,b,c], целые веса ≥0. На левой чаше a и b, на правой c. Верни left, right или equal.','a,b,c=data\nreturn "left" if a+b>c else "right" if a+b<c else "equal"',T,'if_else')
    add('tiny_triangle','Три палочки','data — три целые длины ≥0. Верни bool: можно ли построить невырожденный треугольник.','a,b,c=sorted(data)\nreturn a+b>c',T,'if_else')
    add('middle_value','Дежурный между крайними','data — три целых числа. Верни среднее по величине, учитывая повторы.','return sorted(data)[1]',T,'lists')
    add('two_smallest','Два лёгких камня','data — три целых веса ≥0. Верни сумму двух наименьших.','return sum(data)-max(data)',T,'lists')
    add('unique_chime','Одинокий колокол','data — три значения, ровно два из них равны, третье отличается. Верни отличающееся.','a,b,c=data\nreturn c if a==b else b if a==c else a',[[1,1,2],[1,2,1],[2,1,1],[0,7,7],[-1,-1,4],[3,0,3],[5,5,0],[9,8,8]],'if_else')
    add('strict_slope','Три ступени без площадки','data — три числа. Верни bool: они строго возрастают или строго убывают.','a,b,c=data\nreturn a<b<c or a>b>c',T,'if_else')
    add('closest_zero','Ближе к нулю','data=[a,b]. Верни число с меньшим модулем; при равенстве модулей выбери большее число.','a,b=data\nreturn a if (abs(a),-a)<(abs(b),-b) else b',[[-3,3],[2,-5],[0,4],[-7,-2],[5,5],[8,-8],[-1,0],[4,3]],'if_else')
    add('ticket_zone','Билет через границу','data=[старт,финиш], целые 0..99. Зоны — десятки: 0..9,10..19… Поездка стоит 5 плюс 2 за каждую пересечённую границу зон. Верни цену.','return 5+2*abs(data[0]//10-data[1]//10)',[[0,0],[9,10],[10,9],[0,99],[31,38],[20,40],[70,12],[99,90]],'math_ops')
    add('power_bank','Пауэрбанк с потерями','data=[заряд,потери], заряд≥0, потери 0..100 процентов. При передаче сохраняется целая часть заряда*(100-потери)/100. Верни потерянный заряд.','a,p=data\nreturn a-a*(100-p)//100',[[0,0],[100,0],[100,100],[7,10],[99,25],[1,1],[45,50],[80,15]],'math_ops')
    add('bridge_clearance','Мост под парусом','data=[высота_мачты,высота_моста,запас], неотрицательные целые. Проход разрешён только когда над мачтой останется не меньше запаса; равенство допускается. Верни bool.','mast,bridge,gap=data\nreturn bridge-mast>=gap',T,'if_else')
    add('ribbon_wrap','Лента вокруг куба','data — целая длина ребра куба ≥0. Лента дважды огибает куб по двум перпендикулярным квадратам, на узел нужно ещё 15. Верни общую длину.','return 8*data+15',N,'math_ops')
    add('is_power_two','Одна искра в числе','data — неотрицательное целое. Верни bool: его двоичная запись содержит ровно одну единицу. Ноль не подходит.','return data>0 and data&(data-1)==0',N,'math_ops')
    add('binary_width','Длина двоичного имени','data — неотрицательное целое. Верни длину его двоичной записи без префикса; запись нуля имеет длину 1.','return max(1,data.bit_length())',N,'math_ops')
    add('bit_difference','Несовпавшие лампочки','data=[a,b], целые ≥0. Верни число разрядов, в которых их двоичные записи отличаются, дополняя слева нулями.','return bin(data[0]^data[1]).count("1")',P,'math_ops')
    add('half_open','Открытая правая дверь','data=[x,left,right], left≤right. Верни bool: left≤x<right.','x,l,r=data\nreturn l<=x<r',[[0,0,1],[1,0,1],[0,0,0],[-1,-2,0],[4,4,9],[10,4,9],[8,4,9],[3,4,9]],'if_else')
    add('thermal_band','Коридор температур','data=[температура,центр,допуск], допуск≥0. Верни расстояние температуры до допустимого закрытого интервала [центр-допуск,центр+допуск]; внутри 0.','t,c,d=data\nreturn max(0,abs(t-c)-d)',T,'math_ops')
    add('small_change','Монеты по пять и одному','data — сумма ≥0. Верни минимальное число монет номиналом 5 и 1 при неограниченном запасе.','return data//5+data%5',N,'math_ops')
    add('cups_rest','Кружки вверх дном','data — количество кружек ≥0. Каждую вторую перевернули, затем каждую третью перевернули ещё раз. Верни число перевёрнутых кружек среди номеров 1..data.','return data//2+data//3-2*(data//6)',N,'math_ops')
    add('long_dash','Дефис у края','data — строка. Удали все дефисы только с двух краёв. Внутренние дефисы сохрани.','return data.strip("-")',['','-','---','-a-b--','a-b','--x','x--',' -x- '],'strings')
    add('one_split','Левый и правый берег','data — строка с разделителем :. Верни список из части до первого : и всей части после него. Если : нет, вторая часть пустая.','a,sep,b=data.partition(":")\nreturn [a,b]',['a:b','a:b:c',':x','x:','abc','',':','вход:выход'],'strings')
    add('safe_slug','Имя папки без пробелов','data — строка. Удали обычные пробелы по краям, внутренние обычные пробелы замени на _, буквы переведи в нижний регистр.','return data.strip(" ").lower().replace(" ","_")',W,'strings')
    add('double_suffix','Двойной хвост','data — строка. Если она заканчивается на .bak.bak, удали ровно одно .bak; остальные строки сохрани.','return data[:-4] if data.endswith(".bak.bak") else data',['a.bak.bak','a.bak','x.bak.bak.bak','.bak.bak','','bak.bak','a.BAK.bak','a.txt'],'strings')
    add('shop_packs','Коробки с бесплатной четвёртой','data — число покупаемых коробок ≥0. В каждой группе из четырёх одна бесплатна; каждая оплачиваемая стоит 17. Верни стоимость.','return (data-data//4)*17',N,'math_ops')
    add('taxi_wait','Такси на светофоре','data=[поездка,ожидание], минуты ≥0. Первые 3 минуты ожидания бесплатны, затем 4 монеты в минуту; поездка стоит 9 за минуту и 30 за посадку. Верни цену.','ride,wait=data\nreturn 30+9*ride+4*max(0,wait-3)',P,'math_ops')
    add('plant_shade','Растение у окна','data=[час,облака], час 0..23, облака — bool. Верни sun только при часе от 8 до 17 включительно и отсутствии облаков, иначе shade.','h,cloud=data\nreturn "sun" if 8<=h<=17 and not cloud else "shade"',[[7,False],[8,False],[17,False],[18,False],[12,True],[0,False],[23,True],[9,False]],'if_else')
    add('three_switches','Большинство переключателей','data — три значения bool. Лампа горит, если включены хотя бы два. Верни bool.','return sum(data)>=2',[[False,False,False],[True,False,False],[False,True,False],[False,False,True],[True,True,False],[True,False,True],[False,True,True],[True,True,True]],'if_else')
    add('xor_three','Нечётное число ключей','data — три значения bool. Замок открыт, если включено нечётное количество. Верни bool.','return bool(data[0]^data[1]^data[2])',[[False,False,False],[True,False,False],[False,True,False],[False,False,True],[True,True,False],[True,False,True],[False,True,True],[True,True,True]],'if_else')
    add('cyclic_order','Короткая дорога по кругу','data=[n,a,b], n≥1, a,b — позиции 0..n-1. Верни минимальное число шагов по кругу от a до b, можно идти в обе стороны.','n,a,b=data\nreturn min((a-b)%n,(b-a)%n)',[[1,0,0],[8,0,7],[8,2,6],[10,1,8],[7,3,3],[12,10,1],[9,0,4],[5,4,1]],'math_ops')
    add('hour_bells','Удары часовой башни','data — час 0..23. Башня отбивает час по 12-часовой системе; в полночь и полдень 12 ударов. Верни число ударов.','return (data-1)%12+1',[0,1,6,11,12,13,18,23],'math_ops')
    add('photo_fit','Фото в конверте','data=[a,b,c,d], положительные размеры фото a×b и конверта c×d. Поворот на 90° разрешён, края можно касать. Верни bool: помещается ли фото.','a,b,c,d=data\nreturn (a<=c and b<=d) or (b<=c and a<=d)',[[2,3,3,2],[4,4,3,5],[1,1,1,1],[7,2,3,8],[5,3,4,4],[2,8,8,2],[9,1,2,8],[6,6,9,9]],'if_else')
    add('triangle_kind','Треугольник по углам','data — три положительные стороны, образующие треугольник. Верни right, acute или obtuse по квадратам сторон.','a,b,c=sorted(data)\ns=a*a+b*b-c*c\nreturn "right" if s==0 else "acute" if s>0 else "obtuse"',[[3,4,5],[2,2,2],[2,3,4],[5,12,13],[4,5,6],[3,3,5],[7,8,9],[6,8,10]],'if_else')
    add('ceiling_level','Подвесной потолок','data=[высота,потеря,минимум], целые ≥0. После ремонта высота уменьшается на потерю. Верни bool: новая высота не меньше минимума и строго положительна.','h,p,m=data\nreturn h-p>=m and h-p>0',T,'if_else')
    add('three_way_sign','Стрелка разности','data=[a,b]. Верни -1, 0 или 1 в зависимости от знака a-b без вычитания больших чисел.','a,b=data\nreturn int(a>b)-int(a<b)',P+[[-5,2],[3,-1]],'if_else')
    add('book_spread','Разворот книги','data — номер страницы ≥1. В книге разворот содержит чётную страницу слева и следующую нечётную справа. Верни [левая,правая]; перед страницей 1 допустима страница 0.','return [data//2*2,data//2*2+1]',[1,2,3,4,9,10,99,100],'math_ops')
    add('stamp_date','Штамп даты','data=[день,месяц,год], дата корректна, год 1..9999. Верни строку YYYY-MM-DD.','d,m,y=data\nreturn f"{y:04d}-{m:02d}-{d:02d}"',[[1,1,1],[9,2,2024],[31,12,1999],[29,2,2000],[7,10,2026],[30,4,321],[15,8,99],[3,3,3333]],'strings')
    add('square_ring','Номер квадратного кольца','data=[x,y], целые координаты. Кольцо 0 содержит начало, кольцо k состоит из клеток с max(|x|,|y|)=k. Верни число клеток кольца, на котором находится точка (у кольца 0 одна клетка).','r=max(map(abs,data))\nreturn 8*r if r else 1',[[0,0],[1,0],[1,1],[-2,1],[3,-4],[10,0],[5,5],[-7,-3]],'math_ops')
    add('pocket_compass','Четырёхбуквенный компас','data — строка длины 0..4. Дополни её справа точками до длины 4, затем верни строку в обратном порядке.','return data.ljust(4,".")[::-1]',['','n','ne','west','юг','123','a.','....'],'strings')
    add('symmetric_pair','Числа вокруг центра','data=[a,b,c]. Верни bool: a и c находятся на одинаковом расстоянии от b, но не совпадают.','a,b,c=data\nreturn a+c==2*b and a!=c',T+[[1,2,3],[3,2,1]],'if_else')
    add('right_hand_clock','Два циферблата','data=[h1,h2], часы 0..23. Верни число полных часов от первого показания до второго при движении вперёд в пределах суток, для совпадения 0.','return (data[1]-data[0])%24',[[0,0],[23,1],[1,23],[6,12],[12,6],[22,0],[8,9],[0,23]],'math_ops')
    return out
